def transform(grid):
    h,w=len(grid),len(grid[0]); out=[row[:] for row in grid]
    # motif consists of four rows at offsets (0..3,0..1), anchor is 3
    motif={(0,0):1,(0,1):1,(0,2):0, (1,0):0,(1,1):4,(1,2):0, (2,0):0,(2,1):1,(2,2):5, (3,0):4,(3,1):4,(4,0):0}
    # Original motif anchor at (r6,c4) with coordinates as above; all 3-colored isolated anchors receive translation.
    anchors=[]
    for r in range(h):
        for c in range(w):
            if grid[r][c]==3: anchors.append((r,c))
    if not anchors: return out
    # motif is the colored pixels in block spanning rows 6..10, cols 7..9; anchor marker at row6 col4 maps motif origin row6 col7
    # Copy it to each 3 marker with origin offset (0,+3) relative to anchor.
    for r,c in anchors:
        for (dr,dc),v in motif.items():
            rr,cc=r+dr,c+3+dc
            if rr<h and cc<w: out[rr][cc]=v
    return out
